3	import (
4		"fmt"
5		"strings"
6	)
7	
8	// The numbered steps DevDesk writes for the findings it builds itself
9	// (DEVDESK-752). Every function here is pure: the caller says what it ran and
10	// what the tool printed. A step is one imperative sentence in English US with
11	// one action; alternatives are separate steps. The Resolution of the same
12	// finding is untouched.
13	
14	// kustomizeMountStep is added for a kustomize image that could not find a path
15	// (see mountResolution): the container sees only what DevDesk mounts.
16	const kustomizeMountStep = "If this reference points outside the directory DevDesk mounts into the container, " +
17		"scan the enclosing directory or set scan.tools.kustomize.source: binary."
18	
19	// isLoadRestrictor reports whether kustomize refused a file outside the overlay
20	// directory.
21	func isLoadRestrictor(detail string) bool {
22		return strings.Contains(detail, "security; file") && strings.Contains(detail, "is not in or below")
23	}
24	
25	// renderSteps are the steps for a chart or an overlay that did not render.
26	// target is the overlay directory or the chart, relative to the scanned
27	// directory; detail is what the tool printed.
28	func renderSteps(source, target string, from ToolSource, detail string) []string {
29		if source != SourceKustomize {
30			return []string{
31				fmt.Sprintf("Run helm template %s and fix the first error it reports.", target),
32				fmt.Sprintf("If a dependency is missing, run helm dependency build %s.", target),
33			}
34		}
35		var steps []string
36		if isLoadRestrictor(detail) {
37			steps = []string{
38				"Reference a directory that has its own kustomization.yaml, or",
39				fmt.Sprintf("move the file below %s.", target),
40			}
41		} else {
42			steps = []string{fmt.Sprintf("Run kustomize build %s and fix the first error it reports.", target)}
43		}
44		if from == ToolSourceContainer &&
45			(strings.Contains(detail, "evalsymlink failure") || strings.Contains(detail, "no such file or directory")) {
46			steps = append(steps, kustomizeMountStep)
47		}
48		return steps
49	}
50	
51	// helmLintSteps are the steps for one message of helm lint: file is the finding's
52	// file and chart the chart directory.
53	func helmLintSteps(file, chart string) []string {
54		return []string{
55			fmt.Sprintf("Fix what helm lint reports in %s.", file),
56			fmt.Sprintf("Run helm lint %s again to confirm.", chart),
57		}
58	}
59	
60	// schemaSteps are the steps for a field the schema rejected. rendered is "" for
61	// a plain manifest and the renderer's dialect (helm, kustomize) for a rendered
62	// one.
63	func schemaSteps(r kubeconformResource, p kubeconformFieldProblem, version, rendered string) []string {
64		field := p.Path
65		if m := additionalProperty.FindStringSubmatch(p.Msg); m != nil {
66			field = strings.TrimSuffix(p.Path, "/") + "/" + m[1]
67		}
68		if field == "" {
69			field = "the resource"
70		}
71		release := "Kubernetes"
72		if version != "" {
73			release += " " + version
74		}
75		steps := []string{fmt.Sprintf("Correct %s so it matches the %s %s schema of %s.", field, r.Version, r.Kind, release)}
76		if rendered != "" {
77			steps = append(steps, fmt.Sprintf("Render it with %s and validate the output against %s.", rendered, release))
78		}
79		return steps
80	}
81	
82	// secretSteps are the steps for a secret Gitleaks or Trivy found. It returns a
83	// new slice on every call: a shared one would let a caller change every finding.
84	func secretSteps() []string {
85		return []string{
86			"Revoke or rotate this secret where it was issued: treat it as exposed.",
87			"Remove it from the file and read it from a secret store or an environment variable.",
88		}
89	}
