1	package security
2	
3	import (
4		"strings"
5	
6		"github.com/charmbracelet/x/ansi"
7	
8		"github.com/anthnel/devdesk/internal/scan"
9		"github.com/anthnel/devdesk/internal/ui/shortcut"
10	)
11	
12	// The Repro line of a finding detail and what Y copies (DEVDESK-752). The Repro
13	// is the command a scan wrote for a finding of its own, run from the scanned
14	// directory with the tool on this machine. DevDesk shows and copies it; it never
15	// runs it.
16	
17	// reasonToolInContainer is why Y is greyed on a finding the scan reproduced from
18	// a container: what ran there is not the tool installed on this machine.
19	const reasonToolInContainer = "The scan ran this tool in a container, not the one on this machine"
20	
21	// reproNoneInContainer is the Repro line of a finding whose tool ran in a
22	// container.
23	const reproNoneInContainer = "none: the tool ran in a container, not on this machine"
24	
25	// reproCommand is the Repro line of f, trimmed, when it is one line of plain
26	// words. A Repro read back from a cache is text a scanner build wrote: it is
27	// checked again here, as runCommand checks a FixCommand, and trimmed of spaces. A finding the scan
28	// reproduced from a container has none, whatever its cache says.
29	func reproCommand(f scan.Finding) (string, bool) {
30		// Only blanks are trimmed: a trailing line break or carriage return is not
31		// padding, it is text PlainWords refuses.
32		cmd := strings.Trim(f.Repro, " ")
33		if cmd == "" || f.RanFrom == scan.ToolSourceContainer || !scan.PlainWords(cmd) {
34			return "", false
35		}
36		return cmd, true
37	}
38	
39	// copyCommand is what Y copies and whether it can: the command under Run when
40	// there is one, else the Repro line, else the reason there is nothing to copy.
41	func copyCommand(f scan.Finding) (string, shortcut.Availability) {
42		if cmd, ok := runCommand(f); ok {
43			return cmd, shortcut.Availability{}
44		}
45		if cmd, ok := reproCommand(f); ok {
46			return cmd, shortcut.Availability{}
47		}
48		if f.RanFrom == scan.ToolSourceContainer {
49			return "", shortcut.Unavailable(reasonToolInContainer)
50		}
51		return "", shortcut.Unavailable(reasonNoCommand)
52	}
53	
54	// detailsRepro is the Repro line of the Fix block, or nothing. It is cut when it
55	// is wider than the column: the copy key puts the whole of it on the clipboard,
56	// and the line names no key (Rule 134).
57	func detailsRepro(f scan.Finding, t detailsText) []string {
58		const label = "Repro: "
59		if cmd, ok := reproCommand(f); ok {
60			return []string{t.heading(label) + t.text.Render(oneLine("$ "+cmd, t.width-ansi.StringWidth(label)))}
61		}
62		if f.RanFrom == scan.ToolSourceContainer {
63			return t.field(label, reproNoneInContainer, t.text)
64		}
65		return nil
66	}
