		PkgName:     f.PkgName,
		Version:     f.Version,
		FixedIn:     f.FixedIn,
		Class:       f.Class,
		Ecosystem:   f.Ecosystem,
		IaCType:     f.IaCType,
		Resolution:  f.Resolution,
		Steps:       slices.Clone(f.Steps),
		References:  f.References,
		PSSProfile:  pssProfile,
	}
}

